// Normalization script for ReKrute job offers
const items = $input.all();
const output = [];

for (const item of items) {
  const titles = item.json.titles || [];
  const companies = item.json.companies || [];
  const locations = item.json.locations || [];
  const salaries = item.json.salaries || [];

  for (let i = 0; i < titles.length; i++) {
    const title = (titles[i] || '').trim();
    const company = (companies[i] || 'Top Moroccan Enterprise').trim();
    let location = (locations[i] || 'Casablanca').trim();

    // Normalize Moroccan cities
    if (location.toLowerCase().includes('casa')) location = 'Casablanca';
    else if (location.toLowerCase().includes('rabat')) location = 'Rabat';
    else if (location.toLowerCase().includes('tang')) location = 'Tangier';
    else if (location.toLowerCase().includes('marrak')) location = 'Marrakech';
    else if (location.toLowerCase().includes('agad')) location = 'Agadir';

    let salaryMAD = 14500;
    const salText = (salaries[i] || '');
    const match = salText.match(/(\d+)[\s.]?(\d+)?/);
    if (match) {
      salaryMAD = parseInt(match[0].replace(/\s+/g, ''), 10);
    }

    output.push({
      json: {
        title,
        company,
        location,
        source: 'ReKrute',
        contract_type: 'CDI',
        avg_salary_mad: salaryMAD,
        scraped_at: new Date().toISOString()
      }
    });
  }
}

return output;

